from pathlib import Path
import json,os,datetime
B=Path(__file__).parent
P=B/'staged-native11.pages.json'
def read():return json.loads(P.read_text())
def save(pages,done):
 t=P.with_suffix('.tmp');t.write_text(json.dumps(pages,indent=2,ensure_ascii=False)+'\n');os.replace(t,P)
 p=B/'compilation-progress.json';d=json.loads(p.read_text());d['at']=datetime.datetime.now(datetime.timezone.utc).isoformat();d['completed_original_ids']=list(dict.fromkeys(d['completed_original_ids']+done));d['original_completed_count']=len(d['completed_original_ids']);d['staged_item_count']=sum(len(pg['items']) for pg in pages);t=p.with_suffix('.tmp');t.write_text(json.dumps(d,indent=2)+'\n');os.replace(t,p)
def replace(pages,id,statement,strategy,deps=None):
 i=next(i for pg in pages for i in pg['items'] if i['id']==id);i['statement']=statement;i['strategy']=strategy;i['provenance']['statement']='ai-altered';i['provenance']['proof']='not-applicable' if i['kind']=='definition' else 'ai-altered'
 if deps is not None:i['deps']=sorted(set(deps))
 return id
COVER='lem-cyclotomic-projective-covers-and-dualities-descend-through-the-quotient'
